#nullable enable // autogenerated

using MVZ2.GameContent.Buffs.Contraptions;
using MVZ2.GameContent.Buffs.Enemies;
using MVZ2.GameContent.Contraptions;
using MVZ2.GameContent.Damages;
using MVZ2.GameContent.Effects;
using MVZ2.GameContent.Entities;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Level;
using MVZ2Logic.Entities;
using PVZEngine;
using PVZEngine.Buffs;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using UnityEngine;

namespace MVZ2.GameContent.Enemies
{
    [AutoEntityBehaviourDefinition(VanillaEnemyNames.CannonballMannequin)]
    public class CannonballMannequin : AIEntityBehaviour
    {
        public CannonballMannequin(string nsp, string name) : base(nsp, name)
        {
        }
        public override void Init(Entity entity)
        {
            base.Init(entity);
            var buff = entity.AddBuff<FlyBuff>();
            buff.SetProperty(FlyBuff.PROP_TARGET_HEIGHT, 20f);
            HealthLossSpawnHelper.Init(entity, ID);
        }
        protected override void UpdateLogic(Entity entity)
        {
            base.UpdateLogic(entity);
            entity.SetShadowHidden(entity.IsDead);

            // 每损失 100 血触发一次，最多 1 次；触发时 50% 生成 mineTNT，50% 什么都不做  
            HealthLossSpawnHelper.CheckHealthLossTrigger(entity, ID, 100f, 1, e =>
            {
                if (e.RNG.NextFloat() < 0.5f)
                    HealthLossSpawnHelper.SpawnWeightedRandom(e, RandomEntity, RandomEntityWeights);
            });
        }
        // 可召唤实体列表  
        private static NamespaceID[] RandomEntity = new NamespaceID[]
        {
            VanillaContraptionID.mineTNT,
        };

        private static int[] RandomEntityWeights = new int[]
        {
            1,
        };
        public override void PostDeath(Entity entity, DeathInfo info)
        {
            base.PostDeath(entity, info);
            if (entity.WillRemoveOnDeath(info))
                return;
            Explode(entity, entity.GetDamage(), entity.GetFaction());
            entity.Remove();
        }
        public static void Explode(Entity entity, float damage, int faction)
        {
            var scale = entity.GetFinalScale();
            var scaleX = Mathf.Abs(scale.x);
            var range = entity.GetRange() * scaleX;
            if (IsCharged(entity))
            {
                range = range * 2f;
            }

            entity.Explode(entity.GetCenter(), range, faction, damage, new DamageEffectList(VanillaDamageEffects.EXPLOSION, VanillaDamageEffects.DAMAGE_BODY_AFTER_ARMOR_BROKEN, VanillaDamageEffects.MUTE));

            Explosion.Spawn(entity, entity.GetCenter(), range);
            entity.PlaySound(VanillaSoundID.explosion, scaleX == 0 ? 1000 : 1 / (scaleX));
        }
        public override void PostTakeDamage(DamageOutput result)
        {
            base.PostTakeDamage(result);
            if (result.BodyResult == null)
                return;
            if (result.BodyResult.Effects.HasEffect(VanillaDamageEffects.LIGHTNING))
            {
                Charge(result.Entity);
            }
        }


        public static void Charge(Entity tnt)
        {
            if (tnt.HasBuff<TNTChargedBuff>())
                return;
            tnt.AddBuff<TNTChargedBuff>();
        }
        public static bool IsCharged(Entity tnt)
        {
            return tnt.HasBuff<TNTChargedBuff>();
        }
        private static readonly NamespaceID ID = VanillaEnemyID.CannonballMannequin;
    }
}
